function perfectpixel_category_price_range( $html, $category ) {
	global $wpdb;
	$version = (int) get_option( 'perfectpixel_cat_price_version', 1 );
	$key     = 'perfectpixel_cat_price_' . $category->term_id . '_' . $version;
	$range   = get_transient( $key );
	if ( false === $range ) {
		$terms = array_merge( array( (int) $category->term_id ), array_map( 'intval', get_term_children( $category->term_id, 'product_cat' ) ) );
		$tt    = array_map( 'intval', get_terms( array( 'taxonomy' => 'product_cat', 'include' => $terms, 'fields' => 'tt_ids', 'hide_empty' => false ) ) );
		$range = $tt ? $wpdb->get_row(
			"SELECT MIN(l.min_price) AS min_price, MAX(l.max_price) AS max_price FROM {$wpdb->prefix}wc_product_meta_lookup l
			INNER JOIN {$wpdb->term_relationships} tr ON tr.object_id = l.product_id
			INNER JOIN {$wpdb->posts} p ON p.ID = l.product_id AND p.post_status = 'publish'
			WHERE tr.term_taxonomy_id IN (" . implode( ',', $tt ) . ') AND l.max_price > 0',
			ARRAY_A
		) : array();
		set_transient( $key, (array) $range, 12 * HOUR_IN_SECONDS );
	}
	if ( empty( $range['max_price'] ) ) {
		return $html;
	}
	$text = (float) $range['min_price'] === (float) $range['max_price'] ? wc_price( $range['min_price'] ) : wc_format_price_range( $range['min_price'], $range['max_price'] );
	return ' <mark class="count perfectpixel-cat-price">' . wp_kses_post( $text ) . '</mark>';
}

function perfectpixel_category_price_range_flush() {
	update_option( 'perfectpixel_cat_price_version', (int) get_option( 'perfectpixel_cat_price_version', 1 ) + 1, false );
}
